    passages.forEach(passage => {
        const n = Number(passage.unitId.match(/r(\d+)$/)[1]);
        window.KoreanReadingMiddleLessons[passage.unitId] = lessonPlans[n].map((plan, lessonIndex) => {
            const examples = plan.indices.map((questionIndex, exampleIndex) => {
                const question = passage.questions[questionIndex];
                return {
                    label: `예문 ${exampleIndex + 1} · ${passage.title} · ${question.subskill}`,
                    text: question.evidence,
                    analysis: `살필 문제: ${question.question}\n판단: ${question.answer}\n근거 연결: ${question.explanation}`
                };
            });
            const applied = passage.questions[4];
            const distractor = applied.choices.find(choice => choice !== applied.answer);
            examples.push({
                label: `새 상황 적용 · 중${passage.grade - 6} · ${lessonIndex === 0 ? '원리 옮기기' : '오답과 대조하기'}`,
                text: `${applied.question}\n비교할 해석 A: ${applied.answer}\n비교할 해석 B: ${distractor}`,
                analysis: `A가 지문의 원리를 보존한 판단입니다. ${applied.explanation} B는 지문이 제시한 조건·관계·판단 범위를 그대로 유지하는지 대조해 제외합니다. 적용할 근거는 ${applied.evidenceLines.map(index => `${index + 1}행`).join('·')}에서 확인합니다.`
            });
            return {
                title: `중${passage.grade - 6} · ${plan.title}`,
                principle: `${plan.principle} ${gradeFocus[passage.grade]}`,
                rules: plan.rules.slice(), examples,
                example: `${examples[0].text}\n${examples[0].analysis}`,
                tip: plan.tip
            };
        });
    });
    // 같은 스크립트를 다시 읽어도 새 ID가 중복되어 누적되지 않는다.
    const existingIds = new Set(window.ReadingPassages.map(passage => passage.id));
    passages.forEach(passage => {
        if (!existingIds.has(passage.id)) {
            window.ReadingPassages.push(passage);
            existingIds.add(passage.id);
        }
    });
